DELETE FROM exercises WHERE lesson_id = '00000002-0000-0007-0002-000000000001';

UPDATE lessons SET
  slug = 'carnes-lacteos-proteinas',
  title = '{"en": "Meats, Dairy and Proteins", "es": "Carnes, Lácteos y Proteínas"}'::jsonb,
  description = '{"en": "Learn vocabulary for meats, dairy products, and other proteins.", "es": "Aprende vocabulario de carnes, lácteos y otras proteínas."}'::jsonb,
  theory_content = '{"intro": "En esta lección aprenderás el vocabulario de carnes, productos lácteos y otras fuentes de proteína en inglés. Estos alimentos son parte fundamental de la dieta diaria y es importante saber cómo pedirlos o identificarlos en el menú de un restaurante.", "sections": [{"type": "explanation", "title": "SUSTANTIVOS CONTABLES E INCONTABLES", "text": "Algunos alimentos en inglés son contables (''an egg'', ''two eggs'') y otros son incontables (''rice'', ''milk'', ''bread''). Los incontables no se usan con artículos indefinidos y no tienen plural. Para expresar una cantidad de algo incontable usamos expresiones como ''a piece of bread'' (un pedazo de pan), ''a glass of milk'' (un vaso de leche) o ''a bowl of rice'' (un tazón de arroz)."}, {"type": "table", "title": "CARNES, LÁCTEOS Y PROTEÍNAS", "headers": ["English", "Español", "Tipo"], "rows": [["chicken", "pollo", "carne"], ["beef", "carne de res", "carne"], ["fish", "pescado", "carne/proteína"], ["eggs", "huevos", "proteína"], ["milk", "leche", "lácteo"], ["cheese", "queso", "lácteo"], ["yogurt", "yogur", "lácteo"], ["bread", "pan", "carbohidrato"], ["rice", "arroz", "carbohidrato"], ["pasta", "pasta", "carbohidrato"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I eat chicken and rice for lunch.", "es": "Como pollo y arroz en el almuerzo."}, {"en": "She drinks a glass of milk every morning.", "es": "Ella toma un vaso de leche cada mañana."}, {"en": "Would you like some bread and cheese?", "es": "¿Le gustaría algo de pan y queso?"}]}, {"type": "note", "variant": "tip", "text": "''Beef'' se refiere específicamente a la carne de res. ''Meat'' es el término general para carne. Entonces ''chicken'' es pollo (no ''chicken meat'') y ''fish'' es pescado. Solo la carne de res se llama ''beef''."}]}'::jsonb
WHERE id = '00000002-0000-0007-0002-000000000001';

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0002-0007-0001-000000000002', '00000002-0000-0007-0002-000000000001', 1, 'flashcard', '{"text": "chicken", "subtext": "meat / protein"}'::jsonb, '{"text": "pollo", "phonetic": "/ˈtʃɪkɪn/"}'::jsonb, NULL, NULL),
('00000003-0002-0007-0002-000000000002', '00000002-0000-0007-0002-000000000001', 2, 'flashcard', '{"text": "cheese", "subtext": "dairy product"}'::jsonb, '{"text": "queso", "phonetic": "/tʃiːz/"}'::jsonb, NULL, NULL),
('00000003-0002-0007-0003-000000000002', '00000002-0000-0007-0002-000000000001', 3, 'multiple_choice', '{"text": "¿Cómo se dice ''carne de res'' en inglés?"}'::jsonb, '{"text": "beef"}'::jsonb, '["chicken", "fish", "pork"]'::jsonb, '{"es": "''Beef'' es la carne de res. ''Chicken'' es pollo, ''fish'' es pescado y ''pork'' es cerdo."}'::jsonb),
('00000003-0002-0007-0004-000000000002', '00000002-0000-0007-0002-000000000001', 4, 'multiple_choice', '{"text": "Which food is a dairy product?"}'::jsonb, '{"text": "yogurt"}'::jsonb, '["rice", "chicken", "bread"]'::jsonb, '{"es": "''Yogurt'' es un producto lácteo. ''Rice'' es arroz, ''chicken'' es pollo y ''bread'' es pan."}'::jsonb),
('00000003-0002-0007-0005-000000000002', '00000002-0000-0007-0002-000000000001', 5, 'fill_blank', '{"text": "I have ___ and toast for breakfast. (huevos)"}'::jsonb, '{"text": "eggs", "accepted": ["eggs"]}'::jsonb, NULL, '{"es": "''Eggs'' son huevos. Es una proteína popular para el desayuno junto con ''toast'' (pan tostado)."}'::jsonb),
('00000003-0002-0007-0006-000000000002', '00000002-0000-0007-0002-000000000001', 6, 'fill_blank', '{"text": "She drinks a glass of ___ every morning. (leche)"}'::jsonb, '{"text": "milk", "accepted": ["milk"]}'::jsonb, NULL, '{"es": "''Milk'' es leche. Es un sustantivo incontable: ''a glass of milk'' = un vaso de leche."}'::jsonb),
('00000003-0002-0007-0007-000000000002', '00000002-0000-0007-0002-000000000001', 7, 'translation', '{"text": "Como pollo con arroz para el almuerzo."}'::jsonb, '{"text": "I eat chicken and rice for lunch.", "accepted": ["I eat chicken with rice for lunch."]}'::jsonb, NULL, '{"es": "''Chicken'' es pollo y ''rice'' es arroz. ''Lunch'' es el almuerzo. Ambos son incontables en inglés."}'::jsonb),
('00000003-0002-0007-0008-000000000002', '00000002-0000-0007-0002-000000000001', 8, 'translation', '{"text": "¿Quieres pan con queso?"}'::jsonb, '{"text": "Would you like some bread and cheese?", "accepted": ["Do you want some bread and cheese?", "Would you like bread and cheese?"]}'::jsonb, NULL, '{"es": "''Would you like'' es más educado que ''Do you want''. Usamos ''some'' antes de sustantivos incontables."}'::jsonb);

