INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0007-0005-000000000001', '00000001-0000-0000-0000-000000000007', '00000000-0000-0000-0001-000000000001', 5, 'bebidas', '{"en": "Drinks", "es": "Bebidas"}'::jsonb, '{"en": "Learn vocabulary for drinks and how to order them.", "es": "Aprende vocabulario de bebidas y cómo pedirlas."}'::jsonb, 'vocabulary', 20, 12, '{"intro": "En esta lección aprenderás los nombres de las bebidas más comunes en inglés y las frases esenciales para ordenar una bebida en un café, restaurante o bar. Saber pedir una bebida correctamente es una de las habilidades más prácticas del inglés cotidiano.", "sections": [{"type": "explanation", "title": "CÓMO PEDIR UNA BEBIDA", "text": "En inglés hay varias formas de pedir una bebida. La más educada y común es usar ''I''d like'' (Me gustaría), que es la contracción de ''I would like''. También puedes usar ''Can I have...?'' (¿Puedo tener...?) o simplemente ''I want'' aunque esta última es más directa y puede sonar menos cortés. Siempre añade ''please'' al final para ser educado/a."}, {"type": "table", "title": "BEBIDAS COMUNES", "headers": ["English", "Español", "Ejemplo"], "rows": [["water", "agua", "a glass of water"], ["coffee", "café", "a cup of coffee"], ["tea", "té", "a cup of tea"], ["juice", "jugo / zumo", "orange juice"], ["soda", "refresco / gaseosa", "a can of soda"], ["milk", "leche", "a glass of milk"], ["beer", "cerveza", "a cold beer"], ["wine", "vino", "a glass of wine"]]}, {"type": "examples", "title": "EJEMPLOS", "items": [{"label": "Pedir educadamente", "en": "I''d like a coffee, please.", "es": "Me gustaría un café, por favor."}, {"label": "Preguntar", "en": "Can I have a glass of water?", "es": "¿Puedo tener un vaso de agua?"}, {"label": "Ofrecer", "en": "Would you like some tea?", "es": "¿Le gustaría algo de té?"}, {"label": "Negativo", "en": "I don''t drink beer.", "es": "No tomo cerveza."}]}, {"type": "note", "variant": "tip", "text": "''I''d like'' es la forma más educada y más usada para pedir algo en inglés. Memoriza esta frase: ''I''d like a ___, please.'' Te será útil en cafeterías, restaurantes y cualquier lugar donde ordenes algo."}]}'::jsonb, true);

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0005-0007-0001-000000000002', '00000002-0000-0007-0005-000000000001', 1, 'flashcard', '{"text": "coffee", "subtext": "hot drink"}'::jsonb, '{"text": "café", "phonetic": "/ˈkɒfi/"}'::jsonb, NULL, NULL),
('00000003-0005-0007-0002-000000000002', '00000002-0000-0007-0005-000000000001', 2, 'flashcard', '{"text": "juice", "subtext": "drink"}'::jsonb, '{"text": "jugo / zumo", "phonetic": "/dʒuːs/"}'::jsonb, NULL, NULL),
('00000003-0005-0007-0003-000000000002', '00000002-0000-0007-0005-000000000001', 3, 'multiple_choice', '{"text": "¿Cuál es la forma más educada de pedir una bebida?"}'::jsonb, '{"text": "I''d like a water, please."}'::jsonb, '["I want water.", "Give me water.", "Water!"]'::jsonb, '{"es": "''I''d like'' (Me gustaría) es la forma más educada. Siempre añade ''please'' al final para ser cortés."}'::jsonb),
('00000003-0005-0007-0004-000000000002', '00000002-0000-0007-0005-000000000001', 4, 'multiple_choice', '{"text": "What is the English word for ''té''?"}'::jsonb, '{"text": "tea"}'::jsonb, '["coffee", "soda", "juice"]'::jsonb, '{"es": "''Tea'' significa té. Se pronuncia /tiː/."}'::jsonb),
('00000003-0005-0007-0005-000000000002', '00000002-0000-0007-0005-000000000001', 5, 'fill_blank', '{"text": "I''d like a cup of ___, please. (café)"}'::jsonb, '{"text": "coffee", "accepted": ["coffee"]}'::jsonb, NULL, '{"es": "''Coffee'' es café. Decimos ''a cup of coffee'' (una taza de café)."}'::jsonb),
('00000003-0005-0007-0006-000000000002', '00000002-0000-0007-0005-000000000001', 6, 'fill_blank', '{"text": "Can I have a glass of ___, please? (agua)"}'::jsonb, '{"text": "water", "accepted": ["water"]}'::jsonb, NULL, '{"es": "''Water'' es agua. ''A glass of water'' = un vaso de agua."}'::jsonb),
('00000003-0005-0007-0007-000000000002', '00000002-0000-0007-0005-000000000001', 7, 'translation', '{"text": "Me gustaría un jugo de naranja, por favor."}'::jsonb, '{"text": "I''d like an orange juice, please.", "accepted": ["I''d like orange juice, please."]}'::jsonb, NULL, '{"es": "''I''d like'' = Me gustaría. ''Orange juice'' = jugo de naranja. Recuerda ''please'' al final."}'::jsonb),
('00000003-0005-0007-0008-000000000002', '00000002-0000-0007-0005-000000000001', 8, 'translation', '{"text": "¿Te gustaría algo de té o café?"}'::jsonb, '{"text": "Would you like some tea or coffee?", "accepted": ["Would you like tea or coffee?"]}'::jsonb, NULL, '{"es": "''Would you like'' es la forma interrogativa educada para ofrecer algo. ''Some'' se usa para cantidades no especificadas."}'::jsonb);
